        return ResponseEntity.created(URI.create("/reports/" + id)).body(Map.of("id", id));
    }

    @GetMapping("/{id}")
    ResponseEntity<Resource> download(@PathVariable("id") String id) {
        Path file = reportDir.resolve(id + ".csv");
