@RestController
@RequestMapping("/reports")
class ReportController {
    private final S3Client s3;
    private final S3Presigner presigner;
    private final OrderRepository orders;
    private final String bucket;                       // từ cấu hình: REPORTS_BUCKET

    ReportController(S3Client s3, S3Presigner presigner, OrderRepository orders,
                     @Value("${reports.bucket}") String bucket) {
        this.s3 = s3; this.presigner = presigner; this.orders = orders; this.bucket = bucket;
    }

    @PostMapping
    ResponseEntity<Map<String, String>> create(@RequestParam("month") YearMonth month,
                                               @AuthenticationPrincipal Jwt user) {
        String id = UUID.randomUUID().toString();
        s3.putObject(b -> b.bucket(bucket).key(key(user, id)),
                RequestBody.fromString(Csv.of(orders.findByMonth(month))));
        return ResponseEntity.created(URI.create("/reports/" + id)).body(Map.of("id", id));
    }

    @GetMapping("/{id}")
    ResponseEntity<Void> download(@PathVariable("id") String id, @AuthenticationPrincipal Jwt user) {
        String key = key(user, id);                     // chỉ tìm trong báo cáo của chính người gọi
        try {
            s3.headObject(h -> h.bucket(bucket).key(key));
        } catch (S3Exception e) {
            if (e.statusCode() == 404) return ResponseEntity.notFound().build();
            throw e;
        }
        // pod nào cũng trả được: chuyển hướng tới URL ký sẵn, hết hạn sau 5 phút
        URL url = presigner.presignGetObject(p -> p.signatureDuration(Duration.ofMinutes(5))
                .getObjectRequest(g -> g.bucket(bucket).key(key))).url();
        return ResponseEntity.status(HttpStatus.FOUND).location(URI.create(url.toString())).build();
    }

    private static String key(Jwt user, String id) {
        return "reports/" + user.getSubject() + "/" + id + ".csv";
    }
}
